body.tpl-simple { font-family: Georgia, serif; font-size: 11px; color: #334155; margin: 0; padding: 20px; background-color: #ffffff; }
.tpl-simple .header-table { width: 100%; border-bottom: 1px solid #cbd5e1; padding-bottom: 12px; margin-bottom: 15px; }
.tpl-simple .company-name { font-size: 17px; font-weight: normal; color: {{ $accentColor ?: '#0f172a' }}; letter-spacing: 1px; }
.tpl-simple .company-address { font-size: 9px; color: #64748b; font-style: italic; }
.tpl-simple .payslip-title { font-size: 17px; font-weight: normal; color: {{ $accentColor ?: '#0f172a' }}; text-align: right; letter-spacing: 1px; }
.tpl-simple .employee-info-table { width: 100%; background-color: #ffffff; border-top: 1px solid #e2e8f0; border-bottom: 1px solid #e2e8f0; border-collapse: collapse; margin-bottom: 15px; }
.tpl-simple .employee-info-table td { padding: 6px 4px; font-size: 10px; border: none; }
.tpl-simple .meta-label { color: #64748b; font-weight: normal; }
.tpl-simple .meta-val { font-weight: 600; color: #0f172a; }
.tpl-simple .components-table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
.tpl-simple .components-table th { background-color: #ffffff; color: #334155; border-bottom: 2px solid #94a3b8; padding: 6px 4px; font-size: 10px; font-weight: bold; text-transform: uppercase; }
.tpl-simple .components-table td { border-bottom: 1px solid #f1f5f9; padding: 6px 4px; font-size: 10px; }
.tpl-simple .net-pay-box { background-color: #ffffff; border-top: 2px solid #0f172a; border-bottom: 2px solid #0f172a; color: #0f172a; padding: 10px 0; margin-bottom: 15px; }
.tpl-simple .net-amount { font-size: 15px; font-weight: bold; color: {{ $accentColor ?: '#0f172a' }}; }
.tpl-simple .net-words { font-size: 9.5px; font-style: italic; text-align: right; color: #64748b; }
.tpl-simple .footer-note { text-align: center; font-size: 8.5px; color: #94a3b8; margin-top: 20px; border-top: 1px solid #f1f5f9; padding-top: 6px; }
